package com.project.tuitionmanagementapp.admin

import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.Toast
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.GravityCompat
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.fragment.app.Fragment
import androidx.drawerlayout.widget.DrawerLayout
import com.project.tuitionmanagementapp.R
import com.project.tuitionmanagementapp.databinding.ActivityAdminDashboardBinding
import com.project.tuitionmanagementapp.databinding.AdminNavHeaderBinding

class AdminDashboardActivity : AppCompatActivity() {
    private lateinit var binding: ActivityAdminDashboardBinding
    private lateinit var drawerLayout: DrawerLayout
    private lateinit var headerBinding: AdminNavHeaderBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        // Initialize view binding
        binding = ActivityAdminDashboardBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Initialize drawer layout
        drawerLayout = binding.drawerLayout

        // Initialize header binding
        headerBinding = binding.mainHeader

        // Set up edge-to-edge display
        ViewCompat.setOnApplyWindowInsetsListener(binding.root) { view, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            view.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        // Set up custom header functionality
        setupCustomHeader()

        // Set default fragment
        if (savedInstanceState == null) {
            replaceFragment(admin_home())
            binding.navView.setCheckedItem(R.id.admin_home)
            binding.bottomNavigationView.selectedItemId = R.id.admin_home
        }

        setupNavigationDrawer()
        setupBottomNavigation()
    }

    private fun setupCustomHeader() {
        // Set click listener for account icon
        headerBinding.accountIcon.setOnClickListener { view ->
            showProfileDropdown(view)
        }

        // Since there's no menu icon in the header layout, we'll use the app name as a fallback
        // for opening the drawer, or users can swipe from the edge
        try {
            headerBinding.appName.setOnClickListener {
                if (drawerLayout.isDrawerOpen(GravityCompat.START)) {
                    drawerLayout.closeDrawer(GravityCompat.START)
                } else {
                    drawerLayout.openDrawer(GravityCompat.START)
                }
            }
        } catch (e: Exception) {
            Log.d("AdminDashboard", "App name click listener setup failed")
        }
    }

    private fun setupNavigationDrawer() {
        binding.navView.setNavigationItemSelectedListener { menuItem ->
            when (menuItem.itemId) {
                R.id.admin_home -> {
                    replaceFragment(admin_home())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_home
                }
                R.id.admin_account -> {
                    replaceFragment(admin_account())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_account
                }
                R.id.admin_classes -> {
                    replaceFragment(admin_classes())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_classes
                }
                R.id.admin_reports -> {
                    replaceFragment(admin_reports())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_reports
                }
                R.id.admin_addClasses -> {
                    replaceFragment(admin_assign())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_addClasses
                }
            }
            drawerLayout.closeDrawer(GravityCompat.START)
            true
        }
    }

    private fun setupBottomNavigation() {
        binding.bottomNavigationView.setOnItemSelectedListener { menuItem ->
            when (menuItem.itemId) {
                R.id.admin_home -> {
                    replaceFragment(admin_home())
                    binding.navView.setCheckedItem(R.id.admin_home)
                    true
                }
                R.id.admin_account -> {
                    replaceFragment(admin_account())
                    binding.navView.setCheckedItem(R.id.admin_account)
                    true
                }
                R.id.admin_classes -> {
                    replaceFragment(admin_classes())
                    binding.navView.setCheckedItem(R.id.admin_classes)
                    true
                }
                R.id.admin_reports -> {
                    replaceFragment(admin_reports())
                    binding.navView.setCheckedItem(R.id.admin_reports)
                    true
                }
                R.id.admin_addClasses -> {
                    replaceFragment(admin_assign())
                    binding.navView.setCheckedItem(R.id.admin_addClasses)
                    true
                }
                else -> false
            }
        }
    }

    private fun showProfileDropdown(anchorView: View) {
        val popup = androidx.appcompat.widget.PopupMenu(this, anchorView)
        popup.menuInflater.inflate(R.menu.account_menu_admin, popup.menu)

        popup.setOnMenuItemClickListener { menuItem ->
            when (menuItem.itemId) {
                R.id.edit_profile -> {
                    handleEditProfile()
                    true
                }
                R.id.admin_settings -> {
                    handleSettings()
                    true
                }
                R.id.manage_admin -> {
                    handleManageAdmins()
                    true
                }
                // Handle logout if it exists in menu
                else -> {
                    if (menuItem.title.toString().contains("logout", ignoreCase = true)) {
                        handleLogout()
                        true
                    } else false
                        handleLogout()
                    } else false
                }
                else -> false
            }
        }

        popup.show()
    }

    private fun handleEditProfile() {
        Log.d("AdminDashboard", "Edit profile clicked")
    }

    private fun handleSettings() {
        Log.d("AdminDashboard", "Settings clicked")
        // Instead of trying to load a settings fragment that may not exist,
        // redirect to admin_account which can handle admin settings
        replaceFragment(admin_account())
        Toast.makeText(this, "Admin Settings", Toast.LENGTH_SHORT).show()
    }

    private fun handleManageAdmins() {
        Log.d("AdminDashboard", "Manage admins clicked")
        finish()
        // TODO: Clear user session and return to login
            .show()
    }

}
    @Deprecated("Deprecated in Java")
    override fun onBackPressed() {
        if (::drawerLayout.isInitialized && drawerLayout.isDrawerOpen(GravityCompat.START)) {
            drawerLayout.closeDrawer(GravityCompat.START)
        } else {
            super.onBackPressed()
        }
    }
}

package com.project.tuitionmanagementapp.admin

import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.Toast
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.GravityCompat
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.drawerlayout.widget.DrawerLayout
import com.project.tuitionmanagementapp.R
import com.project.tuitionmanagementapp.databinding.ActivityAdminDashboardBinding
import com.project.tuitionmanagementapp.databinding.AdminNavHeaderBinding

class AdminDashboardActivity : AppCompatActivity() {
    private lateinit var binding: ActivityAdminDashboardBinding
    private lateinit var drawerLayout: DrawerLayout
    private lateinit var headerBinding: AdminNavHeaderBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        // Initialize view binding
        binding = ActivityAdminDashboardBinding.inflate(layoutInflater)
        setContentView(binding.root)

        // Initialize drawer layout
        drawerLayout = binding.drawerLayout

        // Initialize header binding
        headerBinding = binding.mainHeader

        // Set up edge-to-edge display with proper padding for bottom navigation
        ViewCompat.setOnApplyWindowInsetsListener(binding.root) { view, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            // Don't apply top padding to root as header handles it
            view.setPadding(systemBars.left, 0, systemBars.right, 0)

            // Apply bottom padding to bottom navigation
            binding.bottomNavigationView.setPadding(
                binding.bottomNavigationView.paddingLeft,
                binding.bottomNavigationView.paddingTop,
                binding.bottomNavigationView.paddingRight,
                systemBars.bottom + 20
            )
            insets
        }

        // Set up custom header functionality
        setupCustomHeader()

        // Set default fragment
        if (savedInstanceState == null) {
            replaceFragment(admin_home())
            binding.navView.setCheckedItem(R.id.admin_home)
            binding.bottomNavigationView.selectedItemId = R.id.admin_home
        }

        setupNavigationDrawer()
        setupBottomNavigation()
    }

    private fun setupCustomHeader() {
        // Set click listener for account icon
        headerBinding.accountIcon.setOnClickListener { view ->
            showProfileDropdown(view)
        }

        // Since there's no menu icon in the header layout, we'll use the app name as a fallback
        // for opening the drawer, or users can swipe from the edge
        try {
            headerBinding.appName.setOnClickListener {
                if (drawerLayout.isDrawerOpen(GravityCompat.START)) {
                    drawerLayout.closeDrawer(GravityCompat.START)
                } else {
                    drawerLayout.openDrawer(GravityCompat.START)
                }
            }
        } catch (e: Exception) {
            Log.d("AdminDashboard", "App name click listener setup failed")
        }
    }

    private fun setupNavigationDrawer() {
        binding.navView.setNavigationItemSelectedListener { menuItem ->
            when (menuItem.itemId) {
                R.id.admin_home -> {
                    replaceFragment(admin_home())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_home
                }
                R.id.admin_account -> {
                    // Launch the proper AdminAccountActivity instead of using a fragment
                    val intent = Intent(this, AdminAccountActivity::class.java)
                    startActivity(intent)
                    true
                }
                R.id.admin_classes -> {
                    replaceFragment(admin_classes())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_classes
                }
                R.id.admin_reports -> {
                    replaceFragment(admin_reports())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_reports
                }
                R.id.admin_addClasses -> {
                    replaceFragment(admin_assign())
                    binding.bottomNavigationView.selectedItemId = R.id.admin_addClasses
                }
            }
            drawerLayout.closeDrawer(GravityCompat.START)
            true
        }
    }

    private fun setupBottomNavigation() {
        binding.bottomNavigationView.setOnItemSelectedListener { menuItem ->
            when (menuItem.itemId) {
                R.id.admin_home -> {
                    replaceFragment(admin_home())
                    binding.navView.setCheckedItem(R.id.admin_home)
                    true
                }
                R.id.admin_account -> {
                    // Launch the proper AdminAccountActivity instead of using a fragment
                    val intent = Intent(this, AdminAccountActivity::class.java)
                    startActivity(intent)
                    true
                }
                R.id.admin_classes -> {
                    replaceFragment(admin_classes())
                    binding.navView.setCheckedItem(R.id.admin_classes)
                    true
                }
                R.id.admin_reports -> {
                    replaceFragment(admin_reports())
                    binding.navView.setCheckedItem(R.id.admin_reports)
                    true
                }
                R.id.admin_addClasses -> {
                    replaceFragment(admin_assign())
                    binding.navView.setCheckedItem(R.id.admin_addClasses)
                    true
                }
                else -> false
            }
        }
    }

    private fun showProfileDropdown(anchorView: View) {
        val popup = androidx.appcompat.widget.PopupMenu(this, anchorView)
        popup.menuInflater.inflate(R.menu.account_menu_admin, popup.menu)

        popup.setOnMenuItemClickListener { menuItem ->
            when (menuItem.itemId) {
                R.id.edit_profile -> {
                    handleEditProfile()
                    true
                }
                R.id.admin_settings -> {
                    handleSettings()
                    true
                }
                R.id.manage_admin -> {
                    handleManageAdmins()
                    true
                }
                R.id.admin_logout -> {
                    handleLogout()
                    true
                }
                else -> false
            }
        }

        popup.show()
    }

    private fun handleEditProfile() {
        Log.d("AdminDashboard", "Edit profile clicked")
        Toast.makeText(this, "Edit Profile functionality will be implemented", Toast.LENGTH_SHORT).show()
    }

    private fun handleSettings() {
        Log.d("AdminDashboard", "Settings clicked")
        // Instead of trying to load a settings fragment that may not exist,
        // redirect to admin_account which can handle admin settings
        replaceFragment(admin_account())
        Toast.makeText(this, "Admin Settings", Toast.LENGTH_SHORT).show()
    }

    private fun handleManageAdmins() {
        Log.d("AdminDashboard", "Manage admins clicked")
        // Use admin_account fragment which handles user management
        replaceFragment(admin_account())
        Toast.makeText(this, "User Management", Toast.LENGTH_SHORT).show()
    }

    private fun handleLogout() {
        // Show a confirmation dialog before logging out
        android.app.AlertDialog.Builder(this)
            .setTitle("Logout")
            .setMessage("Are you sure you want to logout?")
            .setPositiveButton("Yes") { _, _ ->
                // Clear user session data (you may want to use SharedPreferences or your auth system)
                val sharedPrefs = getSharedPreferences("TuitionAppPrefs", MODE_PRIVATE)
                val editor = sharedPrefs.edit()
                editor.remove("admin_logged_in")
                editor.remove("admin_id")
                editor.remove("admin_name")
                editor.remove("admin_email")
                // Add any other admin data that needs to be cleared
                editor.apply()

                // Show toast message
                Toast.makeText(this, "Logged out successfully", Toast.LENGTH_SHORT).show()

                // Redirect to login screen
                val intent = Intent(this, com.project.tuitionmanagementapp.auth.LoginActivity::class.java)
                intent.flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
                startActivity(intent)
                finish()
            }
            .setNegativeButton("No", null)
            .show()
    }

    private fun replaceFragment(fragment: Fragment) {
        try {
            supportFragmentManager.beginTransaction()
                .replace(R.id.frameLayoutID, fragment)
                .commit()
        } catch (e: Exception) {
            Log.e("AdminDashboard", "Error replacing fragment", e)
        }
    }

    @Deprecated("Deprecated in Java")
    override fun onBackPressed() {
        if (::drawerLayout.isInitialized && drawerLayout.isDrawerOpen(GravityCompat.START)) {
            drawerLayout.closeDrawer(GravityCompat.START)
        } else {
            super.onBackPressed()
        }
    }
}

package com.project.tuitionmanagementapp.admin

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.*
import androidx.recyclerview.widget.RecyclerView
import com.project.tuitionmanagementapp.R

class AttendanceAdapter(
    private val students: List<AttendanceRecord>,
    private val onStatusChange: (String, String) -> Unit // studentId, status
) : RecyclerView.Adapter<AttendanceAdapter.AttendanceViewHolder>() {

    inner class AttendanceViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        val studentName: TextView = itemView.findViewById(R.id.tvStudentName)
        val studentId: TextView = itemView.findViewById(R.id.tvStudentId)
        val statusGroup: RadioGroup = itemView.findViewById(R.id.statusGroup)
        val btnPresent: RadioButton = itemView.findViewById(R.id.btnPresent)
        val btnAbsent: RadioButton = itemView.findViewById(R.id.btnAbsent)
        val btnLate: RadioButton = itemView.findViewById(R.id.btnLate)
        val notes: EditText = itemView.findViewById(R.id.edtNotes)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): AttendanceViewHolder {
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_attendance_student_row, parent, false)
        return AttendanceViewHolder(view)
    }

    override fun onBindViewHolder(holder: AttendanceViewHolder, position: Int) {
        val record = students[position]

        holder.studentName.text = record.studentName
        holder.studentId.text = "ID: ${record.studentId}"
        holder.notes.setText(record.notes)

        // Set initial status
        when (record.status) {
            "present" -> holder.btnPresent.isChecked = true
            "absent" -> holder.btnAbsent.isChecked = true
            "late" -> holder.btnLate.isChecked = true
        }

        // Handle status changes
        holder.statusGroup.setOnCheckedChangeListener { _, checkedId ->
            val status = when (checkedId) {
                R.id.btnPresent -> "present"
                R.id.btnAbsent -> "absent"
                R.id.btnLate -> "late"
                else -> "absent"
            }
            onStatusChange(record.studentId, status)
        }

        // Apply theme colors
        holder.btnPresent.setTextColor(holder.itemView.context.getColor(R.color.green))
        holder.btnAbsent.setTextColor(holder.itemView.context.getColor(R.color.red))
        holder.btnLate.setTextColor(holder.itemView.context.getColor(R.color.yellow))
    }

    override fun getItemCount() = students.size

    fun markAllAs(status: String) {
        students.forEach { student ->
            onStatusChange(student.studentId, status)
        }
        notifyDataSetChanged()
    }
}

package com.project.tuitionmanagementapp.admin

import android.os.Bundle
import android.widget.ImageView
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.github.mikephil.charting.charts.PieChart
import com.github.mikephil.charting.data.PieData
import com.github.mikephil.charting.data.PieDataSet
import com.github.mikephil.charting.data.PieEntry
import com.google.firebase.firestore.FirebaseFirestore
import com.project.tuitionmanagementapp.R
import java.text.SimpleDateFormat
import java.util.*

class AttendanceSheetActivity : AppCompatActivity() {

    private lateinit var firestore: FirebaseFirestore
    private lateinit var pieChart: PieChart
    private lateinit var recyclerView: RecyclerView
    private lateinit var tvTotalStudents: TextView
    private lateinit var tvPresent: TextView
    private lateinit var tvAbsent: TextView
    private lateinit var tvClassName: TextView
    private lateinit var tvDate: TextView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_attendance_sheet)

        initializeViews()
        setupPieChart()

        // Get data from intent
        val classId = intent.getStringExtra("classId") ?: return
        val date = intent.getLongExtra("date", System.currentTimeMillis())

        loadAttendanceData(classId, date)

        // Back button
        findViewById<ImageView>(R.id.backButton).setOnClickListener {
            finish()
        }
    }

    private fun initializeViews() {
        firestore = FirebaseFirestore.getInstance()
        pieChart = findViewById(R.id.pieChartAttendance)
        recyclerView = findViewById(R.id.rvAttendance)
        tvTotalStudents = findViewById(R.id.tvTotalStudents)
        tvPresent = findViewById(R.id.tvPresent)
        tvAbsent = findViewById(R.id.tvAbsent)
        tvClassName = findViewById(R.id.tvClassName)
        tvDate = findViewById(R.id.tvDate)
    }

    private fun setupPieChart() {
        pieChart.apply {
            description.isEnabled = false
            setUsePercentValues(true)
            setDrawEntryLabels(false)
            legend.isEnabled = true
            legend.textSize = 12f
            legend.textColor = context.getColor(R.color.purple_700)
            setEntryLabelColor(context.getColor(R.color.white))
            setHoleColor(context.getColor(R.color.white))
            setTransparentCircleColor(context.getColor(R.color.white))
        }
    }

    private fun loadAttendanceData(classId: String, date: Long) {
        firestore.collection("attendance")
            .whereEqualTo("classScheduleId", classId)
            .whereEqualTo("date", date)
            .get()
            .addOnSuccessListener { documents ->
                val records = documents.toObjects(AttendanceRecord::class.java)
                updateUI(records)
                updatePieChart(records)
                setupRecyclerView(records)
            }
    }

    private fun updateUI(records: List<AttendanceRecord>) {
        val totalStudents = records.size
        val presentCount = records.count { it.status == "present" }
        val absentCount = records.count { it.status == "absent" }

        tvTotalStudents.text = "Total Students: $totalStudents"
        tvPresent.text = "Present: $presentCount"
        tvAbsent.text = "Absent: $absentCount"

        if (records.isNotEmpty()) {
            tvClassName.text = records.first().className
            tvDate.text = SimpleDateFormat("MMMM dd, yyyy", Locale.getDefault())
                .format(Date(records.first().date))
        }
    }

    private fun updatePieChart(records: List<AttendanceRecord>) {
        val entries = ArrayList<PieEntry>()

        val presentCount = records.count { it.status == "present" }
        val absentCount = records.count { it.status == "absent" }
        val lateCount = records.count { it.status == "late" }

        if (presentCount > 0) entries.add(PieEntry(presentCount.toFloat(), "Present"))
        if (absentCount > 0) entries.add(PieEntry(absentCount.toFloat(), "Absent"))
        if (lateCount > 0) entries.add(PieEntry(lateCount.toFloat(), "Late"))

        val dataSet = PieDataSet(entries, "Attendance").apply {
            colors = listOf(
                getCompatColor(R.color.green),
                getCompatColor(R.color.red),
                getCompatColor(R.color.yellow)
            )
            valueTextSize = 14f
            valueTextColor = getCompatColor(R.color.white)
        }

        pieChart.data = PieData(dataSet)
        pieChart.invalidate()
    }

    private fun setupRecyclerView(records: List<AttendanceRecord>) {
        recyclerView.layoutManager = LinearLayoutManager(this)
        recyclerView.adapter = AttendanceAdapter(records) { _, _ -> }
    }

    private fun getCompatColor(colorRes: Int): Int {
        return ContextCompat.getColor(this, colorRes)
    }
}

