                    }
                    is Teacher -> {
                        teachersList.remove(user)
                        Toast.makeText(context, "Teacher deleted successfully", Toast.LENGTH_SHORT).show()
                    }
                }
                initializeData()
                filterUsers(searchView.query.toString(), currentFilter)
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

