                "Student Performance Report",
                "Teacher Performance Report",
                "Payment Status Report"
            )
            val adapter = ArrayAdapter(requireContext(), android.R.layout.simple_spinner_item, reportTypes)
            adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
            this.adapter = adapter
        }

        val generateButton = Button(requireContext()).apply {
            text = "Generate Report"
            setOnClickListener {
                val reportType = reportTypeSpinner.selectedItem.toString()
                val newReport = "$reportType - ${getCurrentDate()}"
