        try {
            view?.findViewById<TextView>(R.id.tvReportCount)?.text = "Available Reports: ${reportsList.size}"
        } catch (e: Exception) {
            // Handle missing view
        }
    }
        val cancelButton = Button(requireContext()).apply {
            text = "Cancel"
            setOnClickListener {
                dialog.dismiss()
            }
        }

        view.addView(TextView(requireContext()).apply { text = "Select Report Type:" })
        view.addView(reportTypeSpinner)
        view.addView(generateButton)
        view.addView(cancelButton)

        dialog.setContentView(view)
        dialog.show()
    }

    private fun showExportDialog() {
