package com.project.tuitionmanagementapp.models

import com.google.firebase.Timestamp
import java.util.Date

data class Payment(
    val id: String = "",
    val studentId: String = "",
    val amount: Double = 0.0,
    val paymentMethod: String = "",
    val referenceNumber: String = "",
    val paymentDate: Date = Date(),
    val paymentMonth: String = "", // Format: YYYY-MM
    val note: String = "",
    val processedBy: String = "",
    val status: String = "Completed", // "Completed", "Failed", "Refunded"
    val receiptUrl: String = "",
    val lastUpdated: Date = Date()
) {
    // Calculate next due date (1 month from payment date)
    fun getNextDueDate(): Date {
        val calendar = java.util.Calendar.getInstance()
        calendar.time = paymentDate
        calendar.add(java.util.Calendar.MONTH, 1)
        return calendar.time
    }

    // Convert to Map for Firestore
    fun toMap(): Map<String, Any> {
        return mapOf(
            "studentId" to studentId,
            "amount" to amount,
            "paymentMethod" to paymentMethod,
            "referenceNumber" to referenceNumber,
            "paymentDate" to Timestamp(paymentDate),
            "paymentMonth" to paymentMonth,
            "note" to note,
            "processedBy" to processedBy,
            "status" to status,
            "receiptUrl" to receiptUrl,
            "lastUpdated" to Timestamp(lastUpdated)
        )
    }
}

// Enum class for payment methods
enum class PaymentMethod(val displayName: String) {
    CASH("Cash"),
    CREDIT_CARD("Credit Card"),
    DEBIT_CARD("Debit Card"),
    BANK_TRANSFER("Bank Transfer"),
    MOBILE_PAYMENT("Mobile Payment")
}

// Enum class for payment status
enum class PaymentStatus(val displayName: String, val colorResId: Int) {
    PAID("Paid", android.graphics.Color.GREEN),
    PENDING("Pending", android.graphics.Color.YELLOW),
    OVERDUE("Overdue", android.graphics.Color.RED)
}

package com.project.tuitionmanagementapp.models
data class Student( val id: String = "", val firstName: String = "", val lastName: String = "", val dateOfBirth: String = "", val gender: String = "", val nicNumber: String = "", val studentPhone: String = "", val studentEmail: String = "", val address: String = "", val city: String = "", val studentId: String = "", val classCategories: List<String> = emptyList(), val currentGrade: String = "", val admissionDate: String = "", val guardianName: String = "", val guardianPhone: String = "", val guardianEmail: String = "", val guardianAddress: String = "", val medicalConditions: String = "", val notes: String = "", val studentUserId: String = "", val guardianUserId: String = "", val registrationDate: String = "", val lastUpdated: String = "", val registeredBy: String = "", val profileImageUrl: String = "", val isActive: Boolean = true, // Financial properties val totalFees: Double = 0.0, val paidAmount: Double = 0.0, val pendingAmount: Double = 0.0, // Additional properties for StudentRepository val paymentStatus: String = "", val attendanceRate: Double = 0.0, val gradeAverage: Double = 0.0, val photoUrl: String = profileImageUrl, // Keep backward compatibility for existing code val email: String = studentEmail, val grade: String = currentGrade, val phone: String = studentPhone, val enrollmentDate: String = admissionDate, val school: String = "" ) { val fullName: String get() = "$firstName $lastName"
fun getDisplayInfo(): String = "$firstName $lastName - $currentGrade" }

package com.project.tuitionmanagementapp.models
data class Teacher( val id: String = "", val firstName: String = "", val lastName: String = "", val dateOfBirth: String = "", val gender: String = "", val nicNumber: String = "", val email: String = "", val phone: String = "", val emergencyContact: String = "", val emergencyContactName: String = "", val address: String = "", val city: String = "", val teacherId: String = "", val subjects: List<String> = emptyList(), val classCategories: List<String> = emptyList(), val experience: String = "", val specializations: List<String> = emptyList(), val joiningDate: String = "", val employmentType: String = "", val salary: String = "", val workingDays: List<String> = emptyList(), val bio: String = "", val notes: String = "", val teacherUserId: String = "", val createdDate: String = "", val lastUpdated: String = "", val createdBy: String = "", val profileImageUrl: String = "", val isActive: Boolean = true, // Keep backward compatibility for existing code val subject: String = subjects.firstOrNull() ?: "", val qualification: String = "", val joinDate: String = joiningDate ) { val fullName: String get() = "$firstName $lastName"
fun getDisplayInfo(): String = "$firstName $lastName - $subject" }

