fun getStudentById(studentId: String): Student? { return students.find { it.id == studentId } }
fun getAllStudents(): List<Student> { return students.toList() }
fun getPaymentHistoryByStudentId(studentId: String): List<Payment> { return paymentHistories.filter { it.studentId == studentId } }
fun getAttendanceRecordsByStudentId(studentId: String): List<Attendance> { return attendanceRecords.filter { it.studentId == studentId } }
fun getClassAssignmentsByStudentId(studentId: String): List<ClassSchedule> { return classAssignments.filter { it.studentId == studentId } }
fun getResultsByStudentId(studentId: String): List<ExamResult> { return results.filter { it.studentId == studentId } }
fun addStudent(student: Student): Boolean { return try { students.add(student) true } catch (e: Exception) { false } }
fun updateStudent(student: Student): Boolean { return try { val index = students.indexOfFirst { it.id == student.id } if (index != -1) { students[index] = student true } else { false } } catch (e: Exception) { false } }
fun deleteStudent(studentId: String): Boolean { return try { students.removeAll { it.id == studentId } true } catch (e: Exception) { false } }
fun searchStudents(query: String): List<Student> { return students.filter { it.name.contains(query, ignoreCase = true) || it.id.contains(query, ignoreCase = true) || it.rollNumber.contains(query, ignoreCase = true) } }

