        adapter = ResultAdapter(resultsList) { result ->
            // Handle edit result click - you can implement edit functionality here
            editResult(result)
        }
        recyclerView.layoutManager = LinearLayoutManager(this)
        recyclerView.adapter = adapter
    }

    private fun editResult(result: ResultModel) {
        // Show edit dialog or navigate to edit screen
        Toast.makeText(this, "Edit result for ${result.studentName}", Toast.LENGTH_SHORT).show()
        // You can implement edit functionality here later
    }

    private fun loadResults() {
        val teacherId = auth.currentUser?.uid ?: return

        progressBar.visibility = View.VISIBLE

        firestore.collection("results")
            .whereEqualTo("teacherId", teacherId)
            .orderBy("uploadDate", com.google.firebase.firestore.Query.Direction.DESCENDING)
            .get()
            .addOnSuccessListener { documents ->
                resultsList.clear()
                for (document in documents) {
                    val result = ResultModel(
                        id = document.id,
                        studentName = document.getString("studentName") ?: "",
                        subject = document.getString("subject") ?: "",
                        className = document.getString("className") ?: "",
                        marks = document.getLong("marks")?.toInt() ?: 0,
                        grade = document.getString("grade") ?: "",
                        comments = document.getString("comments") ?: "",
                        uploadDate = document.getTimestamp("uploadDate")
                    )
                    resultsList.add(result)
                }
                adapter.notifyDataSetChanged()
                progressBar.visibility = View.GONE
            }
            .addOnFailureListener { exception ->
                progressBar.visibility = View.GONE
                Toast.makeText(this, "Failed to load results: ${exception.message}", Toast.LENGTH_SHORT).show()
            }
    }
}

package com.project.tuitionmanagementapp.student
import android.os.Bundle import android.view.LayoutInflater import android.view.View import android.view.ViewGroup import android.widget.Toast import androidx.fragment.app.Fragment import androidx.recyclerview.widget.LinearLayoutManager import androidx.recyclerview.widget.RecyclerView import com.google.firebase.database.FirebaseDatabase import com.project.tuitionmanagementapp.R
class ResultFragment : Fragment() {
private lateinit var resultRecyclerView: RecyclerView private lateinit var resultList: ArrayList<Result> private lateinit var adapter: ResultAdapter
override fun onCreateView( inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle? ): View? { val view = inflater.inflate(R.layout.fragment_result_student, container, false)
resultRecyclerView = view.findViewById(R.id.recyclerViewResults) resultRecyclerView.layoutManager = LinearLayoutManager(requireContext())
resultList = arrayListOf() adapter = ResultAdapter(resultList) resultRecyclerView.adapter = adapter
val studentId = "S001" // TODO: Make dynamic based on login loadResultsFromFirebase(studentId)
return view }
private fun loadResultsFromFirebase(studentId: String) { val database = FirebaseDatabase.getInstance() val resultsRef = database.getReference("results").child(studentId)
resultsRef.get().addOnSuccessListener { snapshot -> resultList.clear()
for (resultSnapshot in snapshot.children) { val result = resultSnapshot.getValue(Result::class.java) result?.let { resultList.add(it) } }
adapter.notifyDataSetChanged() }.addOnFailureListener { Toast.makeText(requireContext(), "Failed to load results", Toast.LENGTH_SHORT).show() } } }
